program='''def transform(grid):
    out = [list(row) for row in grid]
    h, w = len(out), len(out[0])
    # Full monochrome rows and columns are separator lines; recolor them.
    for r in range(h):
        if len(set(out[r])) == 1:
            out[r] = [2] * w
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            for r in range(h):
                out[r][c] = 2
    return out
'''
